function t(
  id: number, slug: string, name: string, short: string, color: string, leagueId: number,
  countryId: string, opts: Partial<Pick<Team, "stadium" | "city" | "founded" | "coach" | "logo" | "website">> = {}
): Team {
  return {
    id, slug, name, shortName: short, logo: opts.logo ?? "",
    color, countryId, leagueId,
    stadium: opts.stadium ?? "استادیوم خانگی",
    city: opts.city ?? name,
    founded: opts.founded ?? 1900,
    coach: opts.coach ?? "سرمربی تیم",
    website: opts.website,
  };
}

